// Fan the client list out into items, and work out the exact window to ask
// Meta about.
//
// The Graph API wants unix seconds. `since`/`until` bracket YESTERDAY in UTC:
// today is still accumulating, so storing it would record a partial day as a
// real one — the single most common way a metrics chart ends up lying.
const response = $input.first().json;
if (!response.ok) {
  throw new Error(`Portal refused the targets request: ${response.error || 'unknown error'}`);
}

const snapshotDate = response.snapshot_date; // YYYY-MM-DD, yesterday per the portal
const dayStart = Math.floor(Date.parse(`${snapshotDate}T00:00:00Z`) / 1000);
const dayEnd = dayStart + 86399;
const apiVersion = $env.META_API_VERSION || 'v21.0';

const clients = response.clients || [];
if (!clients.length) {
  // Not an error: a new install, or every client has analytics switched off.
  return [{ json: { no_clients: true, snapshot_date: snapshotDate } }];
}

return clients.map((c) => ({
  json: {
    ...c,
    snapshot_date: snapshotDate,
    since: dayStart,
    until: dayEnd,
    api_version: apiVersion,
    access_token: c.access_token || $env.META_ACCESS_TOKEN,
    media_count: (c.media || []).length,
  },
}));

// One item per post to refresh.
//
// n8n runs an HTTP node once per input item, so this expansion IS the loop —
// no inner Loop node needed.
//
// Always emits at least one item: an empty output would leave the outer loop
// with nothing to continue on and the whole run would stall on the first
// client that posted nothing this month.
const client = $('One client at a time').item.json;
const media = client.media || [];

if (!media.length) {
  return [{ json: { client_id: client.client_id, no_media: true } }];
}

return media.map((m) => ({
  json: {
    client_id: client.client_id,
    deliverable_id: m.deliverable_id,
    media_id: m.media_id,
    published_at: m.published_at,
    snapshot_date: client.snapshot_date,
    api_version: client.api_version,
    access_token: client.access_token,
    no_media: false,
  },
}));

// Collect every post back into ONE item for a single batched store call.
//
// Per-post HTTP calls are unavoidable — Meta has no bulk insights edge — but
// per-post writes to our own API are not. A client with 30 posts becomes one
// request instead of thirty.
const expanded = $('Expand media list').all();
const mediaObjects = $('Post: media object').all();
const insights = $input.all();

const posts = expanded.map((item, i) => {
  const media = mediaObjects[i]?.json || {};
  const insight = insights[i]?.json || {};

  // A Graph error body has `error` and no `data`; pass null so the portal
  // falls back to the media object's own counts.
  const insightData = insight && Array.isArray(insight.data) ? insight : null;

  return {
    media_id: item.json.media_id,
    deliverable_id: item.json.deliverable_id,
    media: media.error ? {} : media,
    insights: insightData,
  };
});

return [{
  json: {
    client_id: expanded[0].json.client_id,
    date: expanded[0].json.snapshot_date,
    posts,
    // Fed back into the account snapshot as that day's publishing count.
    posts_published_on_date: posts.filter(
      (p) => (p.media?.timestamp || '').slice(0, 10) === expanded[0].json.snapshot_date
    ).length,
  },
}];
